import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.List;
import java.util.function.Consumer;
import java.util.function.Supplier;

// ------------------------------------------------------------------
// 1️⃣  Read the test‑case JSON file into a single string.
// ------------------------------------------------------------------
Path jsonPath = Path.of("humongous-test-case.json");
String rawJson = Files.readString(jsonPath, StandardCharsets.UTF_8);

// ------------------------------------------------------------------
// 2️⃣  Escape the JSON so that it becomes a valid Java string literal.
//     (All double‑quotes inside the JSON must be escaped with \\\\)
// ------------------------------------------------------------------
String escapedJsonLiteral = "\"" + rawJson.replace("\\", "\\\\").replace("\"", "\\\"") + "\"";

// ------------------------------------------------------------------
// 3️⃣  Build the other arguments as *string representations*:
//      • doGC   → a Runnable that simply calls System.gc()
//      • checker→ your existing referenceChecker consumer
//      • gcLogName → the name of the log file you want to analyse
//      • shouldContain / shouldNotContain → Java ArrayLists expressed as strings
// ------------------------------------------------------------------
String doGCLiteral          = "() -> System.gc()";                     // Runnable
String checkerLiteral       = "referenceChecker";                       // Consumer<Object>
String gcLogNameLiteral     = "\"gc-analysis.log\"";                    // String
String shouldContainLiteral = "java.util.Arrays.asList(\"GC pause\")";   // List<String>
String shouldNotContainLit  = "java.util.Arrays.asList(\"OutOfMemoryError\")"; // List<String>

// ------------------------------------------------------------------
// 4️⃣  Call the helper function with the string‑representations.
// ------------------------------------------------------------------
functions.TestObjectGraphAfterGC_doTesting(
    new Object[]{
        escapedJsonLiteral,
        doGCLiteral,
        checkerLiteral,
        gcLogNameLiteral,
        shouldContainLiteral,
        shouldNotContainLit
    }
);
```

### What this does

| Step | Purpose |
|------|---------|
| **Read & escape JSON** | Turns the raw file contents into a *valid Java string literal* (`"…"`), escaping internal quotes and backslashes. |
| **Build literals** | Each argument is passed as a *Java source‑code fragment* (e.g., `"() -> System.gc()"`). |
| **Call the helper** | The `TestObjectGraphAfterGC_doTesting` function receives those fragments, compiles them at runtime, executes the test, and performs the assertions you specified. |

### Quick sanity check

If you prefer to see the exact strings being sent to the helper, add a debug print before the call:

```java
